const entrada = $('Entrada - Cliente').first().json.body;
const anterior = $('Buscar conversa').first().json || {};
const jaConcluida = String(anterior.concluida ?? '').trim().toLowerCase() === 'true';

if (jaConcluida) {
  let parciais = {};
  try {
    parciais = JSON.parse(anterior.dados_parciais || '{}');
  } catch (erro) {
    parciais = {};
  }
  return [{
    json: {
      sessao_id: entrada.sessao_id,
      mensagem_original: entrada.mensagem,
      ...parciais,
      intencao_concluida: true,
      pergunta_retorno: '',
      resposta_cliente: 'Este pedido já foi registrado nesta conversa. Para fazer outro agendamento, inicie uma nova conversa.',
      resumo_conversa: '',
      novo_agendamento: false,
    },
  }];
}

const bruto = $json.text ?? $json.output ?? '';
const limpo = String(bruto)
  .replace(/^\x60\x60\x60json\s*/i, '')
  .replace(/^\x60\x60\x60\s*/i, '')
  .replace(/\s*\x60\x60\x60$/i, '')
  .trim();

let dados;
try {
  dados = JSON.parse(limpo);
} catch (erro) {
  throw new Error('A IA não retornou um JSON válido: ' + erro.message);
}


if (!dados || typeof dados !== 'object' || Array.isArray(dados)) {
  throw new Error('A IA deve retornar um objeto JSON.');
}

let dadosAnteriores = {};
try {
  const parciais = JSON.parse(anterior.dados_parciais || '{}');
  if (parciais && typeof parciais === 'object' && !Array.isArray(parciais)) dadosAnteriores = parciais;
} catch (erro) {
  dadosAnteriores = {};
}

const camposPersistentes = ['nome_tutor', 'telefone', 'nome_pet', 'servico_desejado', 'data_hora_sugerida'];
for (const campo of camposPersistentes) {
  if ((dados[campo] == null || String(dados[campo]).trim() === '') &&
      dadosAnteriores[campo] != null && String(dadosAnteriores[campo]).trim() !== '') {
    dados[campo] = dadosAnteriores[campo];
  }
}

function semAcentos(valor) {
  return String(valor ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

function especieReconhecida(valor) {
  const texto = semAcentos(valor);
  const grupos = [
    ['cachorro', /\b(?:cachorr[oa]s?|caes|cao|cadelas?|canin[oa]s?)\b/],
    ['gato', /\b(?:gat[oa]s?|felin[oa]s?)\b/],
    ['hamster', /\bhamsters?\b/],
    ['coelho', /\bcoelh[oa]s?\b/],
    ['ave', /\b(?:aves?|passaros?|calopsitas?|periquitos?|papagaios?)\b/],
    ['peixe', /\bpeixes?\b/],
    ['tartaruga', /\btartarugas?\b/],
    ['porquinho-da-india', /\bporquinhos?[ -]da[ -]india\b/],
    ['furao', /\b(?:furao|furoes)\b/],
    ['cavalo', /\b(?:cavalos?|eguas?)\b/],
    ['iguana', /\biguanas?\b/],
  ];
  const encontradas = grupos.filter(([, padrao]) => padrao.test(texto)).map(([especie]) => especie);
  return encontradas.length === 1 ? encontradas[0] : null;
}

dados.especie = especieReconhecida(entrada.mensagem) ||
  especieReconhecida(dados.especie) ||
  especieReconhecida(dadosAnteriores.especie);

function normalizarDataHora(valor) {
  if (valor == null || String(valor).trim() === '') return null;
  const texto = String(valor).trim();
  let partes = texto.match(/^(\d{4})-(\d{2})-(\d{2})[ T](\d{1,2}):(\d{2})(?::\d{2})?$/);
  let ano, mes, dia, hora, minuto;
  if (partes) {
    [, ano, mes, dia, hora, minuto] = partes.map(Number);
  } else {
    partes = texto.match(/^(\d{2})\/(\d{2})\/(\d{4})\s*(?:às?|as)?\s*(\d{1,2}):(\d{2})(?::\d{2})?$/i);
    if (!partes) return null;
    [, dia, mes, ano, hora, minuto] = partes.map(Number);
  }
  const data = new Date(Date.UTC(ano, mes - 1, dia, hora, minuto));
  if (data.getUTCFullYear() !== ano || data.getUTCMonth() !== mes - 1 ||
      data.getUTCDate() !== dia || data.getUTCHours() !== hora ||
      data.getUTCMinutes() !== minuto) return null;
  const dois = numero => String(numero).padStart(2, '0');
  return ano + '-' + dois(mes) + '-' + dois(dia) + ' ' + dois(hora) + ':' + dois(minuto);
}

const original = dados.data_hora_sugerida;
dados.data_hora_sugerida = normalizarDataHora(original);
if (original != null && String(original).trim() !== '' && !dados.data_hora_sugerida) {
  dados.intencao_concluida = false;
  dados.pergunta_retorno = 'Qual é a data e o horário desejados? Use DD/MM/AAAA às HH:mm.';
  dados.resposta_cliente = 'Não consegui identificar a data e o horário com segurança. Pode informá-los como DD/MM/AAAA às HH:mm?';
}

const obrigatorios = ['nome_tutor', 'telefone', 'nome_pet', 'especie', 'servico_desejado', 'data_hora_sugerida'];
const faltando = obrigatorios.find(campo => dados[campo] == null || String(dados[campo]).trim() === '');
const perguntas = {
  nome_tutor: 'Qual é o seu nome?',
  telefone: 'Qual é o seu telefone para contato?',
  nome_pet: 'Qual é o nome do seu pet?',
  especie: 'Qual é a espécie do seu pet (por exemplo: cachorro, gato ou hamster)?',
  servico_desejado: 'Qual serviço você deseja agendar?',
  data_hora_sugerida: 'Para qual data e horário você quer agendar? Informe DD/MM/AAAA às HH:mm.',
};
const marcadores = {
  nome_tutor: /\b(nome|chama|tutor)\b/,
  telefone: /\b(telefone|contato|celular|numero)\b/,
  nome_pet: /\b(nome|chama)\b.*\b(pet|animal|cachorro|gato|hamster|coelho)\b/,
  especie: /\b(especie|tipo de animal)\b/,
  servico_desejado: /\b(servico|atendimento|consulta|banho|tosa|vacina|castracao)\b/,
  data_hora_sugerida: /\b(data|dia|horario|hora|quando)\b/,
};
if (faltando) {
  dados.intencao_concluida = false;
  const perguntaIA = semAcentos(dados.pergunta_retorno || dados.resposta_cliente || '');
  const respostaIA = semAcentos(dados.resposta_cliente || '');
  if (!marcadores[faltando].test(perguntaIA) || !marcadores[faltando].test(respostaIA)) {
    dados.pergunta_retorno = perguntas[faltando];
    dados.resposta_cliente = perguntas[faltando];
  }
} else {
  const respostaIA = String(dados.resposta_cliente || '').trim();
  const iaConcluiu = dados.intencao_concluida === true;
  dados.intencao_concluida = true;
  dados.pergunta_retorno = '';
  if (!iaConcluiu || !respostaIA || respostaIA.includes('?')) {
    dados.resposta_cliente = 'Recebemos seu pedido de ' + dados.servico_desejado + ' para ' + dados.nome_pet + ' em ' + dados.data_hora_sugerida + '. Ele ainda depende da confirmação da clínica.';
  }
}
return [{
  json: {
    sessao_id: entrada.sessao_id,
    mensagem_original: entrada.mensagem,
    ...dados,
    novo_agendamento: dados.intencao_concluida === true,
  },
}];

const texto = String($json.chatInput ?? '').trim();

let acao = 'ajuda';
let idAgendamento = null;

if (/^\/listar\s+pendentes$/i.test(texto)) {
  acao = 'listar';
} else if (/^\/notificacoes$/i.test(texto)) {
  acao = 'notificacoes';
} else {
  const resultado = texto.match(/^\/aprovar\s+(\S+)$/i);

  if (resultado) {
    acao = 'aprovar';
    idAgendamento = resultado[1];
  }
}

return [
  {
    json: {
      sessionId: $json.sessionId,
      comando: texto,
      acao,
      id_agendamento: idAgendamento
    }
  }
];

const comando = String($json.comando ?? '').trim().toLowerCase();
const titulo = comando === '/ajuda'
  ? 'Comandos disponíveis:'
  : 'Comando não reconhecido.\n\nComandos disponíveis:';

return [{
  json: {
    text: `${titulo}
• /notificacoes
• /listar pendentes
• /aprovar ID

Exemplo: /aprovar 61`
  }
}];

const pendentes = $input
  .all()
  .map(item => item.json)
  .filter(item =>
    item.id &&
    String(item.status || '').trim().toLowerCase() === 'pendente'
  );

if (pendentes.length === 0) {
  return [
    {
      json: {
        text: 'Não existem agendamentos pendentes no momento.'
      }
    }
  ];
}

const linhas = pendentes.map(item => {
  const tutor = item.nome_tutor || 'Tutor não informado';
  const pet = item.nome_pet || 'Pet não informado';
  const especie = item.especie || 'Espécie não informada';
  const servico = item.servico_desejado || 'Serviço não informado';
  const dataHora = item.data_hora_sugerida || 'Data não informada';

  return `• #${item.id} — ${tutor} — ${pet} (${especie}) — ${servico} — ${dataHora}`;
});

return [
  {
    json: {
      text:
        `Agendamentos pendentes (${pendentes.length}):\n\n` +
        linhas.join('\n\n') +
        `\n\nPara confirmar, use: /aprovar ID`
    }
  }
];

const idSolicitado =
  $('Interpretar comando').first().json.id_agendamento;

const agendamentoEncontrado =
  $json.id !== undefined &&
  $json.id !== null &&
  String($json.id).trim() !== '';

let resultadoAprovacao;

if (!agendamentoEncontrado) {
  resultadoAprovacao = 'nao_encontrado';
} else if (
  String($json.status || '').trim().toLowerCase() !== 'pendente'
) {
  resultadoAprovacao = 'ja_processado';
} else {
  resultadoAprovacao = 'pronto_para_aprovar';
}

return [
  {
    json: {
      ...$json,
      id_solicitado: idSolicitado,
      resultado_aprovacao: resultadoAprovacao
    }
  }
];

return [
  {
    json: {
      text:
        `Não encontrei o agendamento #${$json.id_solicitado}. ` +
        `Use /listar pendentes para consultar os IDs disponíveis.`
    }
  }
];

return [
  {
    json: {
      text: `O agendamento #${$json.id} já está com status ${$json.status}. Nenhuma alteração foi feita.`
    }
  }
];

const agendamento = $('Validar agendamento').first().json;

return [
  {
    json: {
      text: `Agendamento #${agendamento.id} de ${agendamento.nome_tutor} para ${agendamento.nome_pet} confirmado com sucesso.`
    }
  }
];

const avisos = $('Buscar notificações')
  .all()
  .map(item => item.json)
  .filter(item =>
    item.id_comando &&
    String(item.status_processamento).trim().toLowerCase() === 'nao_lida'
  );

if (avisos.length === 0) {
  return [{ json: { text: 'Não há notificações não lidas.' } }];
}

return [
  {
    json: {
      text:
        `Notificações não lidas (${avisos.length}):\n\n` +
        avisos
          .map(item => `• ${item.resposta || item.comando}`)
          .join('\n\n')
    }
  }
];

const pedido = String($('Status - Entrada').first().json.query.id || '');
const linha = $input.first().json || {};
const encontrado = String(linha.id || '') === pedido;
const bruto = encontrado ? String(linha.status || '').trim().toLowerCase() : '';
const status = bruto === 'confirmado' ? 'Confirmado' :
  bruto === 'pendente' ? 'Pendente' : 'Desconhecido';
return [{ json: { id_agendamento: pedido, status, confirmado: status === 'Confirmado' } }];
